const variantScript = `
<script>
(function(){
  const key = 'fanora-slide-variant';
  function setVariant(v){
    if (!document.body) return;
    document.body.setAttribute('data-variant', v || localStorage.getItem(key) || 'motion');
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){ setVariant(); }, { once: true });
  } else {
    setVariant();
  }
  window.addEventListener('message', function(event){
    if(event.data && event.data.type === 'fanora-variant') setVariant(event.data.variant);
  });
})();
</script>`;

function html(title, body, css='') {
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>${title}</title><style>${baseCss}${motionCss}${css}</style>${variantScript}</head><body class="${body.includes('data-dark') ? 'dark' : ''}">${body.replace(' data-dark','')}</body></html>`;
}

