for (const slide of slides) {
  await fs.writeFile(path.join(slidesDir, slide.file), html(slide.label, slide.body, slide.css));
}

const templatePath = '/Users/ouminghai/.codex/skills/huashu-design/assets/deck_index.html';
let index = await fs.readFile(templatePath, 'utf8');
const manifest = slides.map(s => `    { file: "slides/${s.file}", label: "${s.label}" }`).join(',\n');
index = index.replace(/window\.DECK_MANIFEST = \[[\s\S]*?\n  \];/, `window.DECK_MANIFEST = [\n${manifest}\n  ];`);
index = index.replace('<title>Deck · Multi-file Slide Index</title>', '<title>Fanora · 让热爱成为身份，让故事成为作品</title>');
index = index.replace("// window.DECK_OVERVIEW = 'grid';", "window.DECK_OVERVIEW = 'grid';");
index = index.replace('</style>', `
  .tweaks-panel{position:fixed;top:18px;right:20px;z-index:260;width:286px;padding:13px 14px 14px;border-radius:18px;background:rgba(18,13,24,.74);color:#f4f1ea;backdrop-filter:blur(18px);box-shadow:0 18px 56px rgba(0,0,0,.32);font-family:-apple-system,"PingFang SC",sans-serif;transition:transform .25s ease,opacity .25s ease}
  body[data-mode="overview"] .tweaks-panel{opacity:.76}
  .tweaks-head{display:flex;align-items:center;justify-content:space-between;gap:12px}
  .tweaks-title{font-size:13px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#e9e0ee}
  .tweaks-toggle{border:0;background:rgba(255,255,255,.12);color:#fff;width:30px;height:30px;border-radius:999px;cursor:pointer}
  .tweaks-body{margin-top:12px}
  .variant-row{display:grid;grid-template-columns:1fr 1fr 1fr;gap:7px}
  .variant-btn{border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.07);color:#e7deeb;border-radius:10px;padding:9px 0;font-size:13px;font-weight:700;cursor:pointer}
  .variant-btn[aria-pressed="true"]{background:#f4f1ea;color:#21112f;border-color:#f4f1ea}
  .tweaks-note{margin-top:11px;font-size:12px;line-height:1.45;color:rgba(244,241,234,.68)}
  .tweaks-panel[data-collapsed="true"]{width:118px;padding:9px 12px;border-radius:999px}
  .tweaks-panel[data-collapsed="true"] .tweaks-title{font-size:12px;letter-spacing:.06em}
  .tweaks-panel[data-collapsed="true"] .tweaks-title{color:#fff}
  .tweaks-panel[data-collapsed="true"] .tweaks-title::before{content:"Tweaks"}
  .tweaks-panel[data-collapsed="true"] .tweaks-title{font-size:0}
  .tweaks-panel[data-collapsed="true"] .tweaks-title::before{font-size:12px}
  .tweaks-panel[data-collapsed="true"] .tweaks-body{display:none}
  .tweaks-panel[data-collapsed="true"] .tweaks-toggle{width:30px;height:30px}
</style>`);
index = index.replace('<div id="present-ui">', `<div class="tweaks-panel" id="tweaksPanel" data-collapsed="true">
  <div class="tweaks-head"><div class="tweaks-title">Tweaks · 实时变体切换</div><button class="tweaks-toggle" id="tweaksToggle" title="收起或展开">⌁</button></div>
  <div class="tweaks-body">
    <div class="variant-row">
      <button class="variant-btn" data-variant="classic">经典</button>
      <button class="variant-btn" data-variant="motion">动态</button>
      <button class="variant-btn" data-variant="data">数据</button>
    </div>
    <div class="tweaks-note">数据模式会强化信息图、权重条、流程层级和可视化网格。</div>
  </div>
</div>

<div id="present-ui">`);
index = index.replace("const storageKey = 'deck-index-' + location.pathname;", "const storageKey = 'deck-index-' + location.pathname;\n  const variantKey = 'fanora-slide-variant';\n  let activeVariant = localStorage.getItem(variantKey) || 'motion';");
index = index.replace("if (frame.getAttribute('src') !== deck[idx].file) frame.src = deck[idx].file;", "frame.addEventListener('load', () => sendVariant(), { once: true });\n    if (frame.getAttribute('src') !== deck[idx].file) frame.src = deck[idx].file;\n    sendVariant();");
index = index.replace("function prev() { show(Math.max(current - 1, 0)); }", "function prev() { show(Math.max(current - 1, 0)); }\n  function sendVariant() { try { frame.contentWindow.postMessage({ type: 'fanora-variant', variant: activeVariant }, '*'); } catch (_) {} }\n  function setVariant(v) {\n    activeVariant = v;\n    localStorage.setItem(variantKey, v);\n    document.body.setAttribute('data-variant', v);\n    document.querySelectorAll('.variant-btn').forEach(btn => btn.setAttribute('aria-pressed', btn.dataset.variant === v ? 'true' : 'false'));\n    sendVariant();\n  }\n  async function toggleFullscreen() {\n    try {\n      if (!document.fullscreenElement) await document.documentElement.requestFullscreen();\n      else await document.exitFullscreen();\n    } catch (_) {}\n  }");
index = index.replace("if (e.key === 'p' || e.key === 'P') { window.print(); return; }", "if (e.key === 'f' || e.key === 'F') { e.preventDefault(); if (document.body.getAttribute('data-mode') !== 'present') setMode('present'); toggleFullscreen(); return; }\n    if (e.key === 'p' || e.key === 'P') { window.print(); return; }");
index = index.replace("document.getElementById('overviewBtn').addEventListener('click', () => setMode('overview'));", "document.getElementById('overviewBtn').addEventListener('click', () => setMode('overview'));\n  document.getElementById('tweaksToggle').addEventListener('click', () => {\n    const panel = document.getElementById('tweaksPanel');\n    panel.dataset.collapsed = panel.dataset.collapsed === 'true' ? 'false' : 'true';\n  });\n  document.querySelectorAll('.variant-btn').forEach(btn => btn.addEventListener('click', () => setVariant(btn.dataset.variant)));\n  setVariant(activeVariant);");
await fs.writeFile(path.join(root, 'index.html'), index);

await fs.writeFile(path.join(root, 'slides-manifest.json'), JSON.stringify(slides.map(s => ({file:s.file,label:s.label})), null, 2));
console.log(`Built ${slides.length} slides.`);
